    let down = findMinCost(cost, x + 1, y);
    let diag = findMinCost(cost, x + 1, y + 1);

    // Find the minimum among the three paths
    let best = right;
    if (down < best) best = down;
    if (diag < best) best = diag;

    return cost[x][y] + best;
}

