    const right = findMinCost(cost, x, y + 1, dp);
    const down = findMinCost(cost, x + 1, y, dp);
    const diag = findMinCost(cost, x + 1, y + 1, dp);

    const best = Math.min(right, down, diag);

    dp[x][y] = cost[x][y] + best;
    return dp[x][y];
}

